<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { useRoute, useRouter } from 'vue-router';
import { createCompany, getCompany, updateCompany } from '../../services/companies.service';
import { lookupAddressByCep } from '../../services/address.service';
import PageHeader from '../../components/common/PageHeader.vue';
import type { CompanyPayload } from '../../types/company.types';
import { companySchema } from '../../schemas/company.schema';
const route = useRoute(); const router = useRouter(); const id = computed(() => route.params.id as string | undefined); const editing = computed(() => !!id.value); const readonly = computed(() => route.meta.mode === 'view'); const loading = ref(false); const saving = ref(false); const lookingUpCep = ref(false); const error = ref('');
const { setValues, validate } = useForm({ validationSchema: toTypedSchema(companySchema) });
const empty = (): CompanyPayload => ({ name: '', legalName: '', document: '', stateRegistration: '', municipalRegistration: '', taxRegime: '', cnae: '', email: '', phone: '', street: '', number: '', complement: '', neighborhood: '', city: '', cityCode: '', state: '', zipCode: '', countryCode: '1058', countryName: 'Brasil' }); const form = ref<CompanyPayload>(empty());
async function load() { if (!id.value) return; loading.value = true; try { const company = await getCompany(id.value); form.value = { ...company } as unknown as CompanyPayload; } catch { error.value = 'Não foi possível carregar a empresa.'; } finally { loading.value = false; } }
function digits(value: unknown) { return String(value ?? '').replace(/\D/g, ''); }
function maskCep(value: unknown) { const d = digits(value).slice(0, 8); return d.length > 5 ? `${d.slice(0, 5)}-${d.slice(5)}` : d; }
function maskCnpj(value: unknown) { const d = digits(value).slice(0, 14); return d.replace(/^(\d{2})(\d)/, '$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3').replace(/\.(\d{3})(\d)/, '.$1/$2').replace(/(\d{4}\/\d{2})(\d)/, '$1-$2'); }
function maskPhone(value: unknown) { const d = digits(value).slice(0, 11); return d.length > 10 ? d.replace(/^(\d{2})(\d{5})(\d{4})$/, '($1) $2-$3') : d.replace(/^(\d{2})(\d{4})(\d{4})$/, '($1) $2-$3'); }
function maskCepAndLookup(value: unknown) { form.value.zipCode = maskCep(value); if (form.value.zipCode.length === 9) lookupCep(); }
async function lookupCep() { if (readonly.value || !form.value.zipCode) return; lookingUpCep.value = true; error.value = ''; try { const address = await lookupAddressByCep(form.value.zipCode); form.value.street = address.logradouro; form.value.complement = form.value.complement || address.complemento; form.value.neighborhood = address.bairro; form.value.city = address.localidade; form.value.state = address.uf; form.value.cityCode = address.ibge; } catch (err: any) { error.value = err?.message ?? 'Não foi possível consultar o CEP.'; } finally { lookingUpCep.value = false; } }
async function save() { setValues(form.value as any); const result = await validate(); if (!result.valid) { error.value = 'Revise os campos destacados antes de salvar.'; return; } saving.value = true; try { const payload = Object.fromEntries(Object.entries(form.value).map(([k, v]) => [k, v || undefined])) as unknown as CompanyPayload; if (editing.value) await updateCompany(id.value!, payload); else await createCompany(payload); router.push('/companies'); } catch (err: any) { error.value = err?.response?.data?.message ?? 'Não foi possível salvar a empresa.'; } finally { saving.value = false; } }
onMounted(load);
</script>
<template><div><PageHeader :title="readonly ? 'Visualizar empresa' : editing ? 'Editar empresa' : 'Nova empresa'" back-to="/companies" /><v-alert v-if="error" type="error" density="compact" class="mb-4">{{ error }}</v-alert><v-card :loading="loading"><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" label="Nome fantasia" :readonly="readonly" /><v-text-field v-model="form.legalName" label="Razão social" :readonly="readonly" /><v-text-field v-model="form.document" label="CNPJ" @update:model-value="form.document = maskCnpj($event)" :readonly="readonly" /><v-text-field v-model="form.stateRegistration" label="Inscrição estadual" @update:model-value="form.stateRegistration = digits($event)" :readonly="readonly" /><v-text-field v-model="form.municipalRegistration" label="Inscrição municipal" @update:model-value="form.municipalRegistration = digits($event)" :readonly="readonly" /></v-col><v-col cols="12" md="6"><v-select v-model="form.taxRegime" :items="[{ title: 'Simples Nacional', value: '1' }, { title: 'Simples Nacional — excesso de sublimite', value: '2' }, { title: 'Regime Normal', value: '3' }]" label="Regime tributário (CRT)" :readonly="readonly" /><v-text-field v-model="form.cnae" label="CNAE principal" :readonly="readonly" /><v-text-field v-model="form.email" label="E-mail fiscal" :readonly="readonly" /><v-text-field v-model="form.phone" label="Telefone" @update:model-value="form.phone = maskPhone($event)" :readonly="readonly" /></v-col><v-col cols="12"><v-divider class="mb-4" /><div class="text-subtitle-1 mb-2">Endereço do estabelecimento</div><v-row><v-col cols="12" md="4"><v-text-field v-model="form.zipCode" label="CEP" @update:model-value="maskCepAndLookup($event)" :readonly="readonly" :loading="lookingUpCep" hint="Ao sair do campo, o endereço será consultado automaticamente" persistent-hint @blur="lookupCep" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.street" label="Logradouro" :readonly="readonly" /></v-col><v-col cols="12" md="2"><v-text-field v-model="form.number" label="Número" :readonly="readonly" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.complement" label="Complemento" :readonly="readonly" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.neighborhood" label="Bairro" :readonly="readonly" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.city" label="Município" :readonly="readonly" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.cityCode" label="Código IBGE do município" :readonly="readonly" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.state" label="UF" :readonly="readonly" maxlength="2" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.countryCode" label="Código país" :readonly="readonly" /><v-text-field v-model="form.countryName" label="País" :readonly="readonly" /></v-col></v-row></v-col></v-row></v-card-text><v-card-actions><v-spacer /><v-btn variant="outlined" @click="router.push('/companies')">{{ readonly ? 'Voltar' : 'Cancelar' }}</v-btn><v-btn v-if="!readonly" color="primary" variant="outlined" :loading="saving" :disabled="!form.name" @click="save">Salvar</v-btn></v-card-actions></v-card></div></template>
